/**
 * External dependencies
 */
import { registerBlockVariation } from '@wordpress/blocks';
export function registerElementVariation(coreName, { blockDescription, blockIcon, blockTitle, variationName, scope }) {
    registerBlockVariation(coreName, {
        description: blockDescription,
        name: variationName,
        title: blockTitle,
        isActive: blockAttributes => blockAttributes.__woocommerceNamespace === variationName,
        icon: {
            src: blockIcon
        },
        attributes: {
            __woocommerceNamespace: variationName
        },
        scope
    });
}
